// src/components/Sidebar.js
import { NavLink, useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { destinationsAPI } from '../services/api';
import { Dot } from './UI';

export default function Sidebar({ wsConnected }) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [destInfo, setDestInfo] = useState({ s3: null, secondary: null, remote: null, primaryPct: null });

  useEffect(() => {
    async function loadDests() {
      try {
        const dests = await destinationsAPI.list();
        const s3    = dests.find(d => d.dest_type === 'aws_s3' && d.is_active);
        const remote = dests.find(d => d.dest_type === 'remote_sftp' && d.is_active);
        const local  = dests.find(d => d.dest_type === 'local');
        let primaryPct = null;
        if (local) {
          try {
            const { execSync } = require; // won't work in browser — handled by API
          } catch {}
        }
        setDestInfo({ s3, remote, primaryPct });
      } catch {}
    }
    loadDests();
    const t = setInterval(loadDests, 60000);
    return () => clearInterval(t);
  }, []);

  const navItem = (to, icon, label, badge) => (
    <NavLink key={to} to={to} style={({ isActive }) => ({
      display:'flex', alignItems:'center', gap:9, padding:'7px 12px',
      margin:'1px 6px', borderRadius:8, fontSize:12.5, textDecoration:'none',
      transition:'all .15s', userSelect:'none',
      color: isActive ? 'var(--bv-blue)' : 'var(--bv-txt2)',
      background: isActive ? 'var(--bv-blue-dim)' : 'transparent',
    })}
    onMouseEnter={e => { if (!e.currentTarget.classList.contains('active')) e.currentTarget.style.background='var(--bv-bg4)'; }}
    onMouseLeave={e => { if (!e.currentTarget.classList.contains('active')) e.currentTarget.style.background=''; }}>
      {({ isActive }) => (
        <>
          <i className={`ti ti-${icon}`} style={{ fontSize:15, width:17, flexShrink:0,
            color: isActive ? 'var(--bv-blue)' : 'var(--bv-txt3)' }}/>
          <span style={{ flex:1 }}>{label}</span>
          {badge && (
            <span style={{ fontSize:10, padding:'1px 6px', borderRadius:10, fontWeight:600,
              background: badge.color==='red' ? 'var(--bv-red-bg)' : badge.color==='amber' ? 'var(--bv-amber-bg)' : 'var(--bv-green-bg)',
              color: badge.color==='red' ? 'var(--bv-red)' : badge.color==='amber' ? 'var(--bv-amber)' : 'var(--bv-green)' }}>
              {badge.text}
            </span>
          )}
        </>
      )}
    </NavLink>
  );

  return (
    <div style={{ width:200, flexShrink:0, background:'var(--bv-bg2)', borderRight:'1px solid var(--bv-bd)',
      display:'flex', flexDirection:'column', overflow:'hidden' }}>

      {/* Logo */}
      <div style={{ padding:'16px 14px 12px', borderBottom:'1px solid var(--bv-bd)',
        display:'flex', alignItems:'center', gap:10 }}>
        <div style={{ width:34, height:34, background:'linear-gradient(135deg,var(--bv-accent),var(--bv-accent-dark))',
          borderRadius:8, display:'flex', alignItems:'center', justifyContent:'center',
          fontWeight:700, fontSize:13, color:'#fff', flexShrink:0 }}>BV</div>
        <div>
          <div style={{ fontSize:13, fontWeight:500, color:'var(--bv-txt)', lineHeight:1.3 }}>BackupVault</div>
          <div style={{ fontSize:10, color:'var(--bv-cyan)', fontWeight:500 }}>Infrastructure</div>
        </div>
      </div>

      <nav style={{ flex:1, overflowY:'auto', padding:'4px 0' }}>

        <div style={{ padding:'12px 14px 3px', fontSize:10, color:'var(--bv-txt3)',
          letterSpacing:'.1em', textTransform:'uppercase', fontWeight:600 }}>Overview</div>
        {navItem('/dashboard',  'layout-dashboard', 'Dashboard')}
        {navItem('/targets',    'database',         'DB Servers',   { text:'5', color:'green' })}
        {navItem('/jobs',       'list-check',       'Backup Jobs')}
        {navItem('/history',    'history',          'Run History')}
        {navItem('/live-logs',  'terminal-2',       'Live Logs')}

        <div style={{ padding:'12px 14px 3px', fontSize:10, color:'var(--bv-txt3)',
          letterSpacing:'.1em', textTransform:'uppercase', fontWeight:600 }}>Storage Tiers</div>
        {navItem('/primary-dc', 'device-floppy',   'Primary DC',    { text:'87%', color:'red' })}
        {navItem('/secondary',  'server-2',        'Secondary DB')}
        {navItem('/remote',     'building',        'Remote Onsite', destInfo.remote ? { text:'ON', color:'green' } : null)}
        {navItem('/aws-s3',     'brand-aws',       'AWS S3',        destInfo.s3 ? { text:'ON', color:'green' } : null)}

        <div style={{ padding:'12px 14px 3px', fontSize:10, color:'var(--bv-txt3)',
          letterSpacing:'.1em', textTransform:'uppercase', fontWeight:600 }}>System</div>
        {navItem('/destinations','server-2',       'Destinations')}
        {navItem('/users',       'users',          'Users')}
        {navItem('/strategy',    'sitemap',        'Backup Strategy')}
        {navItem('/settings',    'settings',       'Settings')}
      </nav>

      {/* Footer */}
      <div style={{ borderTop:'1px solid var(--bv-bd)', padding:'10px 6px 4px' }}>
        <button onClick={() => { logout(); navigate('/login'); }} style={{
          display:'flex', alignItems:'center', gap:9, padding:'7px 12px', borderRadius:8,
          background:'none', border:'none', color:'var(--bv-red)', fontSize:12, width:'100%', cursor:'pointer' }}
          onMouseEnter={e => e.currentTarget.style.background='var(--bv-red-dim)'}
          onMouseLeave={e => e.currentTarget.style.background='none'}>
          <i className="ti ti-logout" style={{ fontSize:15 }}/>  Exit Vault
        </button>
        <div style={{ padding:'6px 14px 6px', fontSize:10, display:'flex', alignItems:'center', gap:6 }}>
          <Dot color={wsConnected?'green':'red'} pulse={wsConnected}/>
          <span style={{ color: wsConnected?'var(--bv-green)':'var(--bv-red)', fontSize:10 }}>
            {wsConnected ? 'Live Connected' : 'Reconnecting...'}
          </span>
        </div>
        {user && <div style={{ padding:'0 14px 10px', fontSize:10, color:'var(--bv-txt3)' }}>{user.name} · v1.0.0</div>}
      </div>
    </div>
  );
}
